!function(){"use strict";const e=(e,a,t,r)=>({prompt:e,options:a,correct:t,feedback:r}),a={titration:{name:"酸碱滴定与误差",type:"实验与数据",length:"约 8 分钟",goal:"能用读数差计算浓度，并解释结果为什么偏高或偏低。",diagnostic:e("用 NaOH 滴定盐酸。滴定管初读数 2.10 mL，末读数 20.60 mL。用掉多少 NaOH？",["20.60 mL","18.50 mL","22.70 mL"],1,["把末读数当成了用量。滴定管开始时已经有读数，要先减掉它。","读数差用对了，接下来判断读数差和实际入瓶体积何时会不同。","读数是液面位置，要用末读数减初读数。"]),concept:["滴定管两个读数都是液面位置。消耗体积＝末读数－初读数。","对 HCl 与 NaOH，反应物质的量之比为 1∶1。用标准液浓度乘实际进入锥形瓶的体积，求待测酸的物质的量。","读数差有时包含没进锥形瓶的液体。先追踪液体去了哪里，再判断公式里的量是被高估还是低估。"],demo:"在虚拟滴定里完成一次「判断终点并记录」。返回后对照自己的初读数、末读数和终点判断。",scene:{kind:"exp",id:"tit",label:"进入手动滴定"},strategy:["标出谁的浓度已知、谁的体积已知，圈出初读数和末读数。","先比较读数差和实际入瓶体积，再检查酸和碱的反应计量比。","把各液体的浓度与对应体积配对。若问误差，只改受影响的量，观察计算结果怎样变化。"],repair:e("另一次滴定的初读数是 2.15 mL，末读数是 19.75 mL。用掉多少标准液？",["19.75 mL","17.60 mL","21.90 mL"],1,["19.75 mL 是读数终点，实际用量要减掉开始的位置。","19.75−2.15＝17.60 mL。","两次位置的差是用量。"]),transfer:e("滴定前滴定管尖嘴有气泡，终点时气泡消失。按读数差计算的盐酸浓度怎样变化？",["偏低","不变","偏高"],2,["追踪液体去向。一部分碱液填进尖嘴，读数差比真正入瓶的体积大。","气泡占用的体积会算进读数差，应比较两种体积。","读数差高估了实际进入锥形瓶的碱液体积，所以计算值偏高。"]),recall:e("用 NaOH 滴定一份已移取的盐酸，若锥形瓶里预先有少量蒸馏水，其余操作正确，所需 NaOH 体积怎样变化？",["变大","不变","变小"],1,["加水改变混合液浓度，先看移入的 HCl 物质的量有没有改变。","移入的 HCl 物质的量保持不变，中和所需 NaOH 的量也不变。","加水只稀释盐酸，移入的 HCl 物质的量保持不变。"])},ions:{name:"离子反应与共存",type:"选择与判断",length:"约 6 分钟",goal:"能结合题干环境，判断两种离子是否会发生反应。",diagnostic:e("题干写着「强酸性无色溶液」。最先要把哪两项加入判断？",["H⁺ 与颜色限制","OH⁻ 与颜色限制","只判断能否生成沉淀"],0,["先圈题干的限制，再查反应。","强酸性对应较多 H⁺，OH⁻ 是碱性的线索。","还要考虑 H⁺、颜色，以及生成气体或弱电解质。"]),concept:["先圈环境词，如强酸、强碱、无色。把环境提供的离子一并检查。","再检查是否生成沉淀、气体或弱电解质，也要留意可能的氧化还原。","写一个最小反例。只要有一组离子会反应，就能排除该组合。"],demo:"在「碳酸钠」物质页查性质。尝试用 H⁺ 与 CO₃²⁻ 写出会生成气体的净离子反应。",scene:{kind:"sub",id:"na2co3",label:"查看碳酸钠性质"},strategy:["圈出题目的酸碱性和颜色限制，把题干额外提供的离子写到旁边。","把可能反应的离子两两配对，检查能否生成沉淀、气体或弱电解质。","用一条净离子方程式支撑你的排除理由，再检查电荷和原子是否守恒。"],repair:e("题干说溶液呈强碱性。判断共存时，哪种题干提供的离子要一并检查？",["H⁺","Cl⁻","OH⁻"],2,["H⁺ 是强酸性题干的线索。","题干没有提供 Cl⁻，强碱性要考虑 OH⁻。","读到强碱性，先把 OH⁻ 写进检查表。"]),transfer:e("在强碱性溶液中，哪组离子能大量共存？",["Na⁺、NO₃⁻","Mg²⁺、Cl⁻","NH₄⁺、Cl⁻"],0,["这两种离子与 OH⁻ 无明显反应。","Mg²⁺ 与 OH⁻ 可生成 Mg(OH)₂ 沉淀。","NH₄⁺ 能与 OH⁻ 反应，不能大量共存。"]),recall:e("在题设为无色的溶液中，哪种离子首先因为颜色被排除？",["Na⁺","MnO₄⁻","NO₃⁻"],1,["钠离子在水溶液中无色。","高锰酸根使溶液呈紫色。","硝酸根在水溶液中无色。"])},redox:{name:"氧化还原与电子守恒",type:"定量与守恒",length:"约 7 分钟",goal:"能先找化合价变化，再用电子守恒求物质的量。",diagnostic:e("Fe²⁺ → Fe³⁺ 时，一个铁离子怎样变化？",["得到一个电子","失去一个电子","失去两个电子"],1,["正电荷增加了 1，说明少了一个负电荷。","化合价升高 1，对应失去一个电子。","比较 +2 与 +3，变化量为 1。"]),concept:["给发生变化的元素标出反应前后的价态。","每个原子的化合价变化量要乘原子数和对应物质的量。","失电子的总量等于得电子的总量，写等式后再求未知量。"],demo:"打开铜锌原电池，结合演示辨认哪一极失电子。写出 Zn → Zn²⁺ 的电子变化。",scene:{kind:"exp",id:"cell",label:"观察铜锌原电池"},strategy:["圈出发生价态变化的元素，写清反应前后的价态。","把单个原子得失的电子数乘原子数，再乘对应的物质的量。","让失电子总量等于得电子总量，并检查等式两边用的是同一种单位。"],repair:e("Cu²⁺ 变为 Cu。一个 Cu²⁺ 发生了什么变化？",["失去两个电子","得到两个电子","得到一个电子"],1,["正电荷变少，说明得到了负电荷。","从 +2 变到 0，一个 Cu²⁺ 得到两个电子。","从 +2 变到 0，价态变了 2。"]),transfer:e("Zn 变为 Zn²⁺，Ag⁺ 变为 Ag。0.30 mol Zn 完全反应，对应消耗多少 mol Ag⁺？",["0.15 mol","0.30 mol","0.60 mol"],2,["先写 0.30 mol Zn 共失多少 mol 电子。","每个锌原子失两个电子，每个银离子得一个。","0.30×2＝0.60 mol 电子，由等量 Ag⁺ 接收。"]),recall:e("Cl₂ 变成 Cl⁻ 时，1 mol Cl₂ 共得到多少 mol 电子？",["1 mol","2 mol","4 mol"],1,["一个 Cl₂ 含两个氯原子。","每个氯原子从 0 到 −1，两个氯原子共得两个电子。","每个氯原子只变化 1 个价态单位。"])},polarity:{name:"分子结构与极性",type:"结构与解释",length:"约 6 分钟",goal:"能结合分子空间构型，判断键偶极是否抵消。",diagnostic:e("CO₂ 中 C＝O 键有极性。整个 CO₂ 分子是否有极性？",["有极性，因为键有极性","没有极性，因为两个键偶极抵消","由分子相对质量决定"],1,["还要看两个键偶极的方向和分子的构型。","CO₂ 是直线形，两个相同键偶极方向相反。","判断分子极性要看偶极的合成。"]),concept:["先判断各键有没有偶极，再确认分子的真实空间构型。","比较各键偶极的大小和方向。对称分布的相同偶极可能抵消。","CO₂ 直线形，两个 C＝O 偶极抵消。H₂O 是弯曲形，两个 O—H 偶极不能完全抵消。"],demo:"旋转水分子观察两根 O—H 键的夹角，想一想两支偶极箭头能不能正好反向。",scene:{kind:"mol",id:"h2o",label:"打开水分子模型"},strategy:["先画或辨认真实空间构型，标出要比较的键。","给各键画偶极箭头，分别看大小、方向和对称关系。","检查箭头合成后是否为零，用构型和方向写出理由。"],repair:e("CS₂ 呈直线形，两个相同的 C＝S 键分列两侧。它的合成偶极怎样？",["两个键偶极抵消","两个键偶极相加","由两个硫原子的质量决定"],0,["相同键沿相反方向对称排列，偶极抵消。","两支箭头方向相反，不能沿同一方向相加。","先比较各键偶极的大小和方向。"]),transfer:e("CH₄ 是正四面体，四个 C—H 键相同。整个分子是否有极性？",["有极性，键太多了","没有极性，偶极对称抵消","必须先知道分子质量"],1,["键的数目本身无法决定偶极的合成。","正四面体的四个相同键偶极对称抵消。","空间对称性和各键偶极已足以判断。"]),recall:e("NH₃ 是三角锥形，三个 N—H 键相同。它的键偶极能完全抵消吗？",["能，三个键就一定抵消","能，三个氢原子相同","不能，三角锥形仍有合成偶极"],2,["三个键的方向由空间构型决定。","键相同只说明偶极大小相同，还需检查方向。","三个偶极在对称轴方向的分量合成，NH₃ 有极性。"])}};Object.assign(a,{dilution:{name:"物质的量浓度与稀释",type:"定量计算",concept:["浓度等于溶质的物质的量除以溶液体积。","只加水时，溶质的物质的量守恒。","计算时两边体积用同一单位，定容读的是最终溶液体积。"],demo:"在配制溶液的虚拟实验里找出定容这一步，观察容量瓶的刻度线。",scene:{kind:"exp",id:"cfgsol",label:"去看溶液配制"},strategy:["把稀释前后的浓度和体积分别写成两列。","只加水时写出 c₁V₁＝c₂V₂。","两边体积单位保持一致，检查稀释后的浓度是否更小。"],diagnostic:e("只加水稀释，溶质的物质的量怎样变化？",["增大","保持不变","减小"],1,["加进去的是水。","原溶质的量没变。","减少的是单位体积内的溶质。"]),repair:e("一份 NaCl 溶液加水，哪项不变？",["原来溶解的 NaCl 物质的量","溶液体积","NaCl 浓度"],0,["加水不增加也不移除 NaCl。","体积变大。","浓度降低。"]),transfer:e("溶质保持不变，体积变为原来的 4 倍，浓度变为多少？",["4 倍","不变","1/4"],2,["体积变大，浓度变小。","浓度和体积的乘积不变。","浓度与体积成反比。"]),recall:e("50.0 mL 0.300 mol/L 溶液加水定容至 150.0 mL，浓度为多少？",["0.900 mol/L","0.100 mol/L","0.150 mol/L"],1,["稀释后浓度应更小。","体积变为三倍，浓度变为三分之一。","用 50.0 除以 150.0。"])},cell:{name:"原电池的电子流向",type:"实验与方向",concept:["先写氧化半反应。失电子的一极是原电池的负极。","外电路中电子从负极流向正极。","盐桥里是离子移动，和外导线的电子移动分开考虑。"],demo:"在铜锌原电池演示里跟踪导线箭头，找出电子从哪一侧出发。",scene:{kind:"exp",id:"cell",label:"去看铜锌原电池"},strategy:["圈出两种电极与电解质，找谁发生氧化。","写失电子和得电子的半反应。","分清外电路电子、常规电流和电解质中的离子。"],diagnostic:e("在铜锌原电池中，Zn 变成 Zn²⁺。Zn 是哪一极？",["正极","负极","盐桥"],1,["Zn 失电子。","失电子一侧是负极。","盐桥不充当电极。"]),repair:e("原电池里，某金属失电子。这一侧是？",["正极","负极","没有电极"],1,["先区分得、失电子。","失电子为氧化，对应负极。","发生半反应的这一侧是电极。"]),transfer:e("下列哪项由外导线承担？",["电子传递","盐桥离子迁移","溶液搅拌"],0,["外导线传递电子。","离子在电解质和盐桥内迁移。","导线接通外电路。"]),recall:e("铜锌原电池外导线中，常规电流方向是？",["锌极到铜极","铜极到锌极","沿盐桥"],1,["这是电子移动的方向。","常规电流与电子移动方向相反。","题目问外导线。"])},equilibrium:{name:"化学平衡与浓度变化",type:"原理判断",concept:["动态平衡时，正、逆反应速率相等。","改变某种物质的浓度时，先看这次改变影响哪边。","固定温度时平衡常数保持不变，催化剂使平衡更快建立。"],demo:"打开反应速率演示，观察条件变化对速率的作用。再想一想催化剂能不能改变平衡组成。",scene:{kind:"exp",id:"ratelab",label:"查看反应速率实验"},strategy:["写出可逆反应式，确认条件改变前处于平衡。","标出改变的是浓度、温度、压强还是催化剂。","区分到达平衡的快慢和达到平衡后的组成。"],diagnostic:e("可逆反应达到动态平衡，正、逆反应速率的关系是？",["正大于逆","相等","都停止"],1,["速率不等会改变组成。","正、逆速率相等，反应仍发生。","动态平衡不意味着反应停止。"]),repair:e("平衡时测得组成保持稳定，微观上发生什么？",["只有逆反应","只有正反应","两个方向同时进行且一样快"],2,["仍有正反应。","仍有逆反应。","反应继续进行，速率相等。"]),transfer:e("恒温恒容的 A(g) ⇌ B(g) 达平衡后，加入 B，会向哪边移动？",["向 A","向 B","不移动"],0,["逆反应先加快，消耗部分 B。","先看加入的是生成物。","改变浓度可打破原平衡。"]),recall:e("同一可逆反应在恒温下改变浓度，平衡常数 K 怎样变化？",["不变","一定增大","一定减小"],0,["给定反应的 K 由温度决定。","浓度变化不等于 K 增大。","温度不变时 K 不变。"])},ester:{name:"羧酸、醇与酯化反应",type:"有机反应判断",concept:["先找羧基 —COOH 和醇羟基 —OH。","乙酸和乙醇可逆反应生成乙酸乙酯和水。","生成的酯键可用 —COO— 辨认。"],demo:"旋转乙酸分子，找出同一个碳上的羰基和羟基，认出羧基。",scene:{kind:"mol",id:"ch3cooh",label:"观察乙酸结构"},strategy:["分别圈出羧酸和醇的官能团。","写出酯键，再用反应物的碳链拼出产物。","检查碳骨架、产物名称和同时生成的水。"],diagnostic:e("在 CH₃COOH 里，羧基是哪一段？",["—CH₃","—COOH","—CH₂—"],1,["—CH₃ 是甲基。","羧基写成 —COOH。","在结构式里找羰基与羟基相连的一段。"]),repair:e("下列哪一个是羧酸的特征官能团？",["—COOH","—CHO","碳碳双键"],0,["—COOH 是羧基。","—CHO 是醛基。","羧酸的特征是羧基。"]),transfer:e("乙酸与甲醇发生酯化，生成的酯是哪一个？",["乙酸乙酯","乙酸甲酯","甲酸乙酯"],1,["醇的碳链来自甲醇。","酸提供乙酸部分，醇提供甲基。","羧酸部分来自乙酸。"]),recall:e("乙酸和乙醇发生酯化时，除了酯，还生成什么？",["氢气","水","二氧化碳"],1,["这里没有发生金属置换。","羧酸与醇酯化同时生成水。","这道题没有生成二氧化碳。"])}});const t={required1:{name:"必修第一册",chapters:["第一章 物质及其变化","第二章 海水中的重要元素——钠和氯","第三章 铁 金属材料","第四章 物质结构 元素周期律"]},required2:{name:"必修第二册",chapters:["第五章 化工生产中的重要非金属元素","第六章 化学反应与能量","第七章 有机化合物","第八章 化学与可持续发展"]},reactions:{name:"选择性必修1 · 化学反应原理",chapters:["第一章 化学反应的热效应","第二章 化学反应速率与化学平衡","第三章 水溶液中的离子反应与平衡","第四章 化学反应与电能"]},structures:{name:"选择性必修2 · 物质结构与性质",chapters:["第一章 原子结构与性质","第二章 分子结构与性质","第三章 晶体结构与性质"]},organic:{name:"选择性必修3 · 有机化学基础",chapters:["第一章 有机化合物的结构特点与研究方法","第二章 烃","第三章 烃的衍生物","第四章 生物大分子","第五章 合成高分子"]}},r={ions:{book:"required1",chapter:0,aliases:["离子反应","离子共存","离子方程式","强酸性","强碱性","碳酸根","沉淀"]},redox:{book:"required1",chapter:0,aliases:["氧化还原","电子守恒","化合价","得电子","失电子","氧化剂","还原剂","高锰酸根"]},dilution:{book:"required1",chapter:1,aliases:["物质的量","物质的量浓度","配制溶液","溶液配制","容量瓶","定容","稀释","c1v1c2v2"]},cell:{book:"required2",chapter:1,aliases:["原电池","铜锌电池","铜锌原电池","电子流向","负极","正极","盐桥","化学能与电能"]},equilibrium:{book:"reactions",chapter:1,aliases:["化学平衡","平衡移动","勒夏特列","动态平衡","催化剂","平衡常数","反应速率"]},titration:{book:"reactions",chapter:2,aliases:["滴定","酸碱中和","滴定误差","气泡","滴定管","终点","初读数","末读数","酚酞"]},polarity:{book:"structures",chapter:1,aliases:["分子极性","分子的极性","键极性","空间构型","分子结构","偶极","二氧化碳","水分子","三氟化硼","co2","h2o","bf3"]},ester:{book:"organic",chapter:2,aliases:["酯化","乙酸","乙醇","乙酸乙酯","酯化反应","羧酸","羧基","醇羟基","官能团"]}},o=e=>e.normalize("NFKC").toLowerCase().replace(/[^\p{L}\p{N}]/gu,"");window.ChemStudyContent={topics:a,books:t,locations:r,findTopics:function(e){const l=o(e);return l?Object.keys(r).map(e=>{const{book:n,chapter:c,aliases:i}=r[e],s=[a[e].name,t[n].name,t[n].chapters[c],...i].map(o);return{id:e,score:Math.max(...s.map(e=>e===l?100:l.length>=2&&e.includes(l)?70:e.length>=2&&l.includes(e)?30+Math.min(e.length,20):0))}}).filter(e=>e.score>0).sort((e,a)=>a.score-e.score).map(e=>e.id):[]},reviewDelay:864e5,grade:function(e,a){return{correct:a===e.correct,feedback:e.feedback[a]}}}}();
